4\cdot1989a^4c^2-1989a^2c^2-4\cdot 1989a^2b^2c^2+1989c^2b^4&=(2ab+28c^2)(a^2b^2+4a^2c^2+4b^2c^2+4a^3bc+4ab^3c+c^4+a^4-b^4)\\
4\cdot1989a^4c^2-1989a^2c^2&=(2ab+28c^2)(a^2b^2+4a^2c^2+4b^2c^2+4a^3bc+4ab^3c+c^4+a^4-b^4)-4\cdot 1989a^2b^2c^2+1989c^2b^4\\
4\cdot 1989a^4c^2-1989a^2c^2&=(2ab+28c^2)\cdot (2ab^3+28ab^3+a^3b+2a^2c^2+4ac^3+4b^2c^2+a^2b^3+2ab^2c+28ab^2c+c^4)\\
&\quad+ a^4-b^4-4\cdot 1989a^2b^2c^2+1989c^2b^4\\
4\cdot 1989a^4c^2-1989a^2c^2&=(2ab+28c^2)\cdot  (2a^3b+28a^3b+a^3b+2a^2c^2+4ac^3+4b^2c^2+a^2b^3+2ab^2c\\

